      answer: "Use Edge Runtime with ReadableStream to push data to client. Client uses EventSource API to receive updates.",
      example: "// app/api/notifications/route.js\nexport const runtime = 'edge';\n\nexport async function GET() {\n  const encoder = new TextEncoder();\n  \n  const stream = new ReadableStream({\n    start(controller) {\n      controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: 'connected' })}\\n\\n`));\n      \n      const interval = setInterval(() => {\n        const notification = {\n          id: Date.now(),\n          message: `New update at ${new Date().toLocaleTimeString()}`,\n        };\n        controller.enqueue(encoder.encode(`data: ${JSON.stringify(notification)}\\n\\n`));\n      }, 10000);\n      \n      return () => clearInterval(interval);\n    }\n  });\n  \n  return new Response(stream, {\n    headers: {\n      'Content-Type': 'text/event-stream',\n      'Cache-Control': 'no-cache',\n      'Connection': 'keep-alive'\n    }\n  });\n}\n\n// Client component\n'use client';\nimport { useEffect, useState } from 'react';\n\nexport default function Notifications() {\n  const [notifications, setNotifications] = useState([]);\n  \n  useEffect(() => {\n    const eventSource = new EventSource('/api/notifications');\n    \n    eventSource.onmessage = (event) => {\n      const data = JSON.parse(event.data);\n      setNotifications(prev => [data, ...prev].slice(0, 10));\n    };\n    \n    return () => eventSource.close();\n  }, []);\n  \n  return (\n    <div>\n      {notifications.map(n => <div key={n.id}>{n.message}</div>)}\n    </div>\n  );\n}",
